      "support_status": "SUFFICIENT",
      "rationale": "The cited span explicitly states the possibility expressed by the frozen claim."
    }
  },
  "signal_basis": {
    "component_id": "C041.signal_basis",
    "value": "Compare documentary links, timing and missing traces with candidate route predictions, checking whether approval records connect to particular orders, precede placement and show appropriate authority. The surviving evidence may be incomplete, copied or ambiguous.",
    "scope": "Proposed documentary observations, assumed to occur for this assessment; reconstruction is limited by the surviving records.",
